  var NO_CHARGE_REASONS={review:'Revisión',warranty:'Garantía',courtesy:'Cortesía',other:'Otro'};
  function allAppointments(){var seen={},out=[];(state.visitAppointments||[]).concat(state.appointments||[]).forEach(function(a){if(a&&!seen[a.id]){seen[a.id]=1;out.push(a);}});return out.sort(function(a,b){return new Date(b.starts_at)-new Date(a.starts_at);});}
  async function loadVisits(){var since=new Date(Date.now()-14*864e5).toISOString();
    try{var ap=await q(window.sb.from('smyl_appointments').select('id,patient_id,service_id,branch_id,starts_at,status').eq('tenant_id',state.tenant).in('status',['arrived','in_progress','completed','no_show']).gte('starts_at',since).order('starts_at',{ascending:true}).limit(200));state.visitAppointments=ap||[];var ids=state.visitAppointments.map(function(a){return a.id;});state.visitCharges=ids.length?((await q(window.sb.from('smyl_finance_charges').select('appointment_id,status').eq('tenant_id',state.tenant).in('appointment_id',ids)))||[]):[];}catch(e){state.visitAppointments=[];state.visitCharges=[];}
    try{var st=await q(window.sb.from('smyl_finance_settings').select('no_show_fee').eq('tenant_id',state.tenant).maybeSingle());state.noShowFee=Number(st&&st.no_show_fee)||0;state.settingsReady=true;}catch(e){state.noShowFee=0;state.settingsReady=false;}
    try{state.noCharge=(await q(window.sb.from('smyl_appointment_no_charge').select('appointment_id,reason,decided_at').eq('tenant_id',state.tenant).gte('decided_at',since)))||[];state.noChargeReady=true;}catch(e){state.noCharge=[];state.noChargeReady=false;}}
  async function refreshVisits(){if(!state.loaded||state.refreshingVisits)return;state.refreshingVisits=true;try{await loadVisits();await ensurePatientNames();renderVisits();}finally{state.refreshingVisits=false;}}
  function pendingVisits(){var charged={},closed={},rank={completed:0,in_progress:1,arrived:2,no_show:3};state.visitCharges.forEach(function(c){if(c.status!=='voided')charged[c.appointment_id]=1;});state.noCharge.forEach(function(n){closed[n.appointment_id]=1;});
    return state.visitAppointments.filter(function(a){if(charged[a.id]||closed[a.id])return false;if(a.status==='no_show')return state.noShowFee>0;var s=by(state.services,a.service_id);return !(s&&s.reference_price!=null&&Number(s.reference_price)===0);}).sort(function(a,b){return (rank[a.status]-rank[b.status])||(new Date(a.starts_at)-new Date(b.starts_at));});}
  function closedVisits(){var byId={};state.visitAppointments.forEach(function(a){byId[a.id]=a;});return state.noCharge.filter(function(n){return byId[n.appointment_id];}).sort(function(a,b){return new Date(b.decided_at)-new Date(a.decided_at);}).slice(0,10).map(function(n){return {n:n,a:byId[n.appointment_id]};});}
